function sample(rows,t){if(!rows?.length)return null;let lo=0,hi=rows.length-1;if(t<=rows[0][0])return rows[0];if(t>=rows[hi][0])return rows[hi];while(hi-lo>1){let m=(hi+lo)>>1;if(rows[m][0]<=t)lo=m;else hi=m}const a=rows[lo],b=rows[hi],f=(t-a[0])/(b[0]-a[0]);return a.map((v,i)=>typeof v==='number'?v+(b[i]-v)*f:v)}
