function drawMap(o,card,field,r,method,layer,panel,dt){const {ctx,w,h}=prepareCanvas(card.querySelector('.map-canvas')),scale=Math.max(1,Math.min((w-44)/8,(h-42)/4.625)),W=8*scale,H=4.625*scale,left=(w-W+18)/2,top=13+(h-42-H)/2,pt=p=>[p[0]*scale,H-p[1]*scale];ctx.save();ctx.translate(left,top);ctx.fillStyle='#f8fbfd';ctx.fillRect(0,0,W,H);let bf=null,cf=null,fi=0;if(r&&layer!=='wind'){if(layer==='deficit'){fi=frameIndex(r.clarity_frames,o.t);cf=r.clarity_frames[fi]}else{fi=frameIndex(r.belief_frames,o.t);bf=r.belief_frames[fi]}}
 const key=[panel,layer,fi].join('-');let heat=o.heatCache.get(key);if(!heat){heat=document.createElement('canvas');heat.width=512;heat.height=296;const hc=heat.getContext('2d'),sx=64,sy=64;if(layer==='wind'){for(let j=0;j<field.ny;j++)for(let i=0;i<field.nx;i++){const k=(j*field.nx+i)*3;hc.fillStyle=color(Math.hypot(field.v[k],field.v[k+1])/12,palette.wind);hc.fillRect(i*field.dx*sx,296-(j+1)*field.dx*sy,field.dx*sx+1,field.dx*sy+1)}}else if(layer==='deficit'){o.env.cells.forEach((p,i)=>{hc.fillStyle=color(Math.max(0,o.env.targets[i]-cf.q[i])/.7,palette.deficit);hc.fillRect((p[0]-.0625)*sx,296-(p[1]+.0625)*sy,9,9)})}else{for(let j=0;j<37;j++)for(let i=0;i<64;i++){const k=j*64+i;hc.fillStyle=color(layer==='std'?bf.std[k]/1.8:Math.hypot(...bf.mean[k])/12,layer==='std'?palette.std:palette.wind);hc.fillRect(i*8,296-(j+1)*8,9,9)}}o.heatCache.set(key,heat);if(o.heatCache.size>12)o.heatCache.delete(o.heatCache.keys().next().value)}ctx.drawImage(heat,0,0,W,H);
 if(layer==='mean'&&bf){ctx.strokeStyle='#244b64';ctx.lineWidth=.8;for(let j=2;j<37;j+=4)for(let i=2;i<64;i+=4){const v=bf.mean[j*64+i],n=Math.hypot(...v);if(n<.08)continue;const p=pt([(i+.5)*.125,(j+.5)*.125]),len=Math.min(13,3+n*1.1),ux=v[0]/n,uy=-v[1]/n;ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(p[0]+ux*len,p[1]+uy*len);ctx.lineTo(p[0]+ux*(len-3)-uy*2,p[1]+uy*(len-3)+ux*2);ctx.moveTo(p[0]+ux*len,p[1]+uy*len);ctx.lineTo(p[0]+ux*(len-3)+uy*2,p[1]+uy*(len-3)-ux*2);ctx.stroke()}}
 o.env.obstacles.forEach(c=>{const p=pt(c);ctx.fillStyle='#7c8c94';ctx.beginPath();ctx.arc(...p,c[2]*scale,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=1;ctx.stroke()});o.env.regions.forEach(reg=>{const a=pt([reg.bounds[0][0],reg.bounds[1][1]]),rw=(reg.bounds[1][0]-reg.bounds[0][0])*scale,rh=(reg.bounds[1][1]-reg.bounds[0][1])*scale;ctx.strokeStyle='#47685b';ctx.lineWidth=1.2;ctx.strokeRect(a[0],a[1],rw,rh);ctx.font='600 11px Arial';const txt='Region '+reg.label,tw=ctx.measureText(txt).width;ctx.fillStyle='#fffffff0';ctx.fillRect(a[0]+5,a[1]+5,tw+8,16);ctx.fillStyle='#284e40';ctx.fillText(txt,a[0]+9,a[1]+17)});
 const line=(rows,col,dash=[],until=o.t)=>{ctx.beginPath();ctx.strokeStyle=col;ctx.lineWidth=1.8;ctx.setLineDash(dash);let first=true;for(const row of rows){if(row[0]>until)break;const p=pt(row.slice(1,3));if(first)ctx.moveTo(...p);else ctx.lineTo(...p);first=false}ctx.stroke();ctx.setLineDash([])};
 if(r){const isRobot=o.spec.kind==='robot',rows=isRobot?r[method].samples:r.samples;if(isRobot){line(r.reference.samples,'#3c4d58',[5,4],Infinity);line(r.still_air.samples,'#8d9ca7',[1,4],Infinity)}const col=isRobot?(method==='rpcbf'?'#23765e':'#bd603a'):(panel&&o.spec.kind!=='experiment'?'#bc6436':'#1b6f9f');line(rows,col);const a=sample(rows,o.t),p=pt(a.slice(1,3));ctx.fillStyle=col;ctx.strokeStyle='#fff';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(...p,4,0,Math.PI*2);ctx.fill();ctx.stroke();}
 if(o.spec.kind==='wind'){const ps=o.particles[panel];const spawn=()=>{for(let n=0;n<20;n++){const p=[Math.random()*8,Math.random()*4.625,Math.random()*3];if(!o.env.obstacles.some(c=>Math.hypot(p[0]-c[0],p[1]-c[1])<c[2]))return p}return[0,0,0]};while(ps.length<180)ps.push(spawn());ctx.strokeStyle='#244c74b0';ctx.lineWidth=1;for(let k=0;k<ps.length;k++){const p=ps[k],v=fieldSample(field,p),np=[p[0]+v[0]*dt,p[1]+v[1]*dt,p[2]+dt];if(np[0]<0||np[0]>8||np[1]<0||np[1]>4.625||np[2]>4||o.env.obstacles.some(c=>Math.hypot(np[0]-c[0],np[1]-c[1])<c[2])){ps[k]=spawn();continue}ps[k]=np;const a=pt(np),b=pt([np[0]-.045*v[0],np[1]-.045*v[1]]);ctx.beginPath();ctx.moveTo(...b);ctx.lineTo(...a);ctx.stroke()}}
 ctx.strokeStyle='#8d9fac';ctx.lineWidth=.7;ctx.strokeRect(0,0,W,H);ctx.fillStyle='#617586';ctx.font='10px Arial';ctx.textAlign='center';for(const x of [0,2,4,6,8])ctx.fillText(String(x),x*scale,H+13);ctx.textAlign='right';for(const y of [0,2,4])ctx.fillText(String(y),-6,H-y*scale+3);ctx.fillText('x (m)',W,H+24);ctx.textAlign='left';ctx.fillText('y (m)',-19,-3);ctx.restore();}
function drawTrace(canvas,rows,t,horizon,robot){if(!canvas)return;const {ctx,w,h}=prepareCanvas(canvas),left=29,right=w-9,top=15,bottom=h-13;const vals=robot?[r=>Math.hypot(r[3],r[4])]:[r=>r[15],r=>r[16]],colors=robot?['#1b6f9f']:['#1b6f9f','#b7613f'],yMax=robot?Math.max(.5,...rows.filter((_,i)=>i%10===0).map(r=>Math.hypot(r[3],r[4])))*1.08:1;ctx.font='9px Arial';ctx.fillStyle='#637684';ctx.textAlign='left';ctx.fillText(robot?'Speed (m/s)':'Clarity',0,9);if(!robot){ctx.fillStyle=colors[0];ctx.fillText('A',45,9);ctx.fillStyle=colors[1];ctx.fillText('B',62,9)}ctx.strokeStyle='#d4dfe6';ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(left,top);ctx.lineTo(left,bottom);ctx.lineTo(right,bottom);ctx.stroke();ctx.fillStyle='#637684';ctx.textAlign='right';ctx.fillText(robot?yMax.toFixed(1):'1',left-4,top+3);ctx.fillText('0',left-4,bottom+2);ctx.textAlign='left';ctx.fillText('0 s',left,bottom+11);ctx.textAlign='right';ctx.fillText(horizon.toFixed(0)+' s',right,bottom+11);const stride=Math.max(1,Math.floor(rows.length/500));vals.forEach((fn,k)=>{ctx.strokeStyle=colors[k];ctx.lineWidth=1.25;ctx.beginPath();let first=true;for(let i=0;i<rows.length;i+=stride){const row=rows[i];if(row[0]>t)break;const x=left+row[0]/horizon*(right-left),y=bottom-fn(row)/yMax*(bottom-top);if(first)ctx.moveTo(x,y);else ctx.lineTo(x,y);first=false}ctx.stroke()});ctx.strokeStyle='#8d9fac';ctx.setLineDash([2,3]);const x=left+t/horizon*(right-left);ctx.beginPath();ctx.moveTo(x,top);ctx.lineTo(x,bottom);ctx.stroke();ctx.setLineDash([])}
$('#previous').onclick=()=>goto(index-1);$('#next').onclick=()=>goto(index+1);$('#slide-menu').onchange=e=>goto(+e.target.value);$('#notes-toggle').onclick=()=>{$('#notes').hidden=!$('#notes').hidden;$('#notes-toggle').setAttribute('aria-expanded',String(!$('#notes').hidden))};$('#fullscreen').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();document.addEventListener('keydown',e=>{if(/INPUT|SELECT/.test(e.target.tagName))return;if(e.key==='ArrowRight'||e.key==='PageDown'){e.preventDefault();goto(index+1)}if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();goto(index-1)}});window.addEventListener('hashchange',()=>{const n=+location.hash.slice(1)-1;if(Number.isFinite(n)&&n>=0&&n<slides.length&&n!==index){index=n;render()}});json('slides.json').then(s=>{slides=s;$('#slide-menu').innerHTML=s.map((v,i)=>`<option value="${i}">${i+1}. ${esc(v.title)}</option>`).join('');goto(Math.max(0,(+location.hash.slice(1)||1)-1))}).catch(e=>{root.innerHTML=`<div class="math-error">Unable to load presentation: ${esc(e.message)}</div>`;console.error(e)});
